import{z as r,x as p,o,c as l,q as A,j as s,D as e,d as i,s as B,S as t,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"Hopkins 部分相干成像","description":"","frontmatter":{"title":"Hopkins 部分相干成像","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/hopkins-1953-paper.md","filePath":"litho/hopkins-1953-paper.md","lastUpdated":1791413859000}'),C={name:"litho/hopkins-1953-paper.md"};function h(d,a,m,c,k,T){const n=p("Mermaid");return o(),l("div",null,[a[2]||(a[2]=A('<h1 id="hopkins-部分相干成像" tabindex="-1">Hopkins 部分相干成像 <a class="header-anchor" href="#hopkins-部分相干成像" aria-label="Permalink to &quot;Hopkins 部分相干成像&quot;">​</a></h1><div class="epigraph"><p>部分相干成像不是「有一点相干」的口语，而是把空中像强度写成物体频谱的双线性型；交叉系数只含照明与两个投影瞳。</p><footer>—— H. H. Hopkins, On the diffraction theory of optical images, Proc. R. Soc. Lond. A 217, 408 (1953)</footer></div><p>附录对照，不插入主干。<a href="/litho/computational-litho-paper">上一课</a>把计算光刻收成对 Hopkins 前向的可制造逆。本篇对照 1953 年原文：互强度与传递交叉系数从哪来，主干里的 <a href="/litho/hopkins-tcc">Hopkins TCC</a> 课默认已经会用。不重做全芯片 OPC，也不把这篇论文写成 DTCO 的替代教材。Levinson 的书对照从下一篇开始。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干的<a href="/litho/partial-coherence">部分相干</a>已经用 \\(\\sigma\\) 和 TCC 把产线照明说清。缺口是文献：Hopkins 面对的是显微镜与一般光学仪器的部分相干，不是 KrF 胶。1953 年要把 Abbe 的相干叠加与非相干强度叠加收成同一套互强度传播，使任意光源形状、任意光瞳的像强度有可积的核。</p><p>没有这篇，TCC 会像软件开关。有这篇，才看清：掩模（物体透过率）只进一对空间频率，照明与镜头进交叉系数，两者可分离。计算光刻专文里的「固定光源则预计算 TCC」就是这条分离。</p><h3 id="不是产线第一课" tabindex="-1">不是产线第一课 <a class="header-anchor" href="#不是产线第一课" aria-label="Permalink to &quot;不是产线第一课&quot;">​</a></h3><p>附录不从惠更斯原理重讲。主干波动光学已经把衍射与 NA 钉过。本篇只对照：Hopkins 的互强度 \\(J\\) 如何让强度在像面成为双线性，以及为何低 \\(k_1\\) 的 OPC 仍活在这个 1953 年的核上——直到厚掩模逼出严格电磁。</p><p><span class="marginnote">论文写的是光学像强度，没有抗蚀剂。胶核是后来产线加上的紧凑段，不要读成 Hopkins 已经含显影。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Hopkins 用互强度描述部分相干场：两点的互相关沿系统传播，像面强度是互强度的对角。对投影系统，物体频谱的每一对频率 \\((f_1,g_1)\\)、\\((f_2,g_2)\\) 乘传递交叉系数 \\(\\mathrm{TCC}(f_1,g_1;f_2,g_2)\\)，TCC 是照明光瞳与两个错位投影光瞳的重叠积分。照明形状全部进 TCC；换偶极等于换核，不必重解麦克斯韦。</p><p><span class="marginnote">术语翻译：「双线性型」就是像强度不是「一个频率乘一个系数」的线性叠加，而是每一对频率的组合各乘一个系数再加总——TCC 就是给每对频率配的权重表。图形越细，对里的两个频率离得越远，交叉项越重要。</span></p><p>主干 <a href="/litho/hopkins-tcc">hopkins-tcc</a> 把这收成 OPC 可调用的本征展开（和差相干分解）。读 1953 年时对照的是<strong>分离定理</strong>本身，不是 SOCS 的实现细节。Wong 的投影成像教材是这条文献进入光刻教室的桥梁，仍属对照，不插入成像课序的递进。</p>',13)),(o(),s(t,null,{default:e(()=>[B(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20J%5B%22%E4%BA%92%E5%BC%BA%E5%BA%A6%E4%BC%A0%E6%92%AD%22%5D%20--%3E%20TCC%5B%22TCC%3A%20%E7%85%A7%E6%98%8E%20%E2%88%A9%20%E4%B8%A4%E9%94%99%E4%BD%8D%E7%9E%B3%22%5D%0A%20%20M%5B%22%E7%89%A9%E4%BD%93%E9%A2%91%E8%B0%B1%22%5D%20--%3E%20BL%5B%22%E5%8F%8C%E7%BA%BF%E6%80%A7%E5%BC%BA%E5%BA%A6%22%5D%0A%20%20TCC%20--%3E%20BL%0A%20%20BL%20--%3E%20AI%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%20I(x%2Cy)%22%5D%0A%20%20AI%20--%3E%20RES%5B%22%E8%83%B6%E6%A0%B8%3A%20%E4%B8%BB%E5%B9%B2%E5%8F%A6%E5%8A%A0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h3",{id:"与-abbe-的对照",tabindex:"-1"},[i("与 Abbe 的对照 "),E("a",{class:"header-anchor",href:"#与-abbe-的对照","aria-label":'Permalink to "与 Abbe 的对照"'},"​")],-1)),a[4]||(a[4]=E("p",null,"Abbe 观点：每个源点相干成像，再对源非相干积分。Hopkins 观点：先形成互强度核，再对物体积分。数值上等价，计算上 TCC 可预计算。计算光刻选 Hopkins 形式，因为全芯片掩模变、光源暂时固定。这不是 1953 年论文的产线动机，是后人读法。",-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[i("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"部分相干的物理是：扩展源的不同点互不相干，同一源点发出的衍射级在像面相干干涉。双线性型把「对哪一对级相干」编码进 TCC 的支撑：两频率之差进得了照明填充的区域，才有交叉项。\\(\\sigma\\) 越大，TCC 越宽，密图形调制往往掉得快——主干对比度课用过这句，原文给的是核，不是 NILS。产线把照明半径写成相对投影 \\(\\mathrm{NA}\\) 的 \\(\\sigma\\)，是把 Hopkins 的光瞳重叠归一到扫描机合同上；1953 年文本里没有这套符号，对照时不要倒灌。",-1)),(o(),s(t,null,{default:e(()=>[B(n,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%93%AA%E4%B8%80%E5%AF%B9%E8%A1%8D%E5%B0%84%E7%BA%A7%E4%BC%9A%E7%9B%B8%E5%B9%B2%E5%B9%B2%E6%B6%89%EF%BC%9F%22%5D%20--%3E%20D%5B%22%E4%B8%A4%E9%A2%91%E7%8E%87%E5%B7%AE%20%CE%94f%22%5D%0A%20%20D%20--%3E%20T%7B%22%CE%94f%20%E5%9C%A8%E7%85%A7%E6%98%8E%E5%A1%AB%E5%85%85%20%CF%83%C2%B7NA%20%E5%86%85%EF%BC%9F%22%7D%0A%20%20T%20--%3E%7C%22%E5%9C%A8%22%7C%20Y%5B%22%E6%9C%89%E4%BA%A4%E5%8F%89%E9%A1%B9%EF%BC%9A%E7%BA%A7%E5%AF%B9%E7%9B%B8%E5%B9%B2%E5%B9%B2%E6%B6%89%22%5D%0A%20%20T%20--%3E%7C%22%E4%B8%8D%E5%9C%A8%22%7C%20N%5B%22%E6%97%A0%E4%BA%A4%E5%8F%89%E9%A1%B9%EF%BC%9A%E4%B8%A4%E7%8B%AC%E7%AB%8B%E5%BC%BA%E5%BA%A6%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20Y%20--%3E%20S1%5B%22%CF%83%20%E5%B0%8F%EF%BC%9A%E5%8F%AF%E5%B9%B2%E6%B6%89%E7%9A%84%E7%BA%A7%E5%AF%B9%E5%B0%91%EF%BC%8C%E5%83%8F%E5%81%8F%E7%9B%B8%E5%B9%B2%22%5D%0A%20%20Y%20--%3E%20S2%5B%22%CF%83%20%E5%A4%A7%EF%BC%9A%E7%BA%A7%E5%AF%B9%E5%8F%98%E5%A4%9A%EF%BC%8C%E5%AF%86%E7%BA%BF%E8%B0%83%E5%88%B6%E6%8E%89%E5%BE%97%E5%BF%AB%22%5D%0A%20%20S1%20--%3E%20NILS%5B%22%E5%86%B3%E5%AE%9A%E5%AF%B9%E6%AF%94%E5%BA%A6%E4%B8%8E%20NILS%22%5D%0A%20%20S2%20--%3E%20NILS%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<p><span class="marginnote">数字实例：取 \\(\\sigma=0.3\\)，只有频率差小于 \\(0.3\\,\\mathrm{NA}\\) 的衍射级对才有交叉项；\\(\\sigma\\) 提到 0.9，差到 \\(0.9\\,\\mathrm{NA}\\) 的级对都在互相干涉。可干涉的对数暴涨，密线条之间的串扰加深，像的调制深度就往下掉。</span></p><p>厚掩模打破「物体是平面透过率」。1953 年的 \\(M(f)\\) 是薄屏。Erdmann 的严格近场是在物体频谱处替换 \\(M\\)，TCC 光学核可以留下。附录要防的误读是：Hopkins 过时所以 OPC 改 FDTD；过时的是薄屏，不是双线性成像。</p><p><span class="marginnote">为什么重要：全芯片 OPC 跑得起来，靠的正是「光源固定则 TCC 可预计算」这条分离——掩模布局怎么改，核不用重算，只重算矩阵乘法。没有这个分离，逐片重解波动光学的全芯片优化在算力上根本不成立。</span></p><p><span class="marginnote">不要给这篇论文发明 arXiv 编号。出处就是 Proc. Royal Society A, 1953。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本篇不插入主干课序，不替代 <a href="/litho/partial-coherence">partial-coherence</a> 的 \\(\\sigma\\) 定义课。不把 Hopkins 写成已经包含矢量成像与浸没。不讨论未公开的全芯片 TCC 压缩比。下一篇 Levinson 教材对照的是整本产线原理，不是再积一次 TCC。</p><p><span class="marginnote">计算光刻专文把逆问题放在这个前向之上。读 Hopkins 是为了知道逆的是哪一个算子，不是为了在 1953 年里找 ILT。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 1953：像强度是物体频谱的双线性型，TCC 只含照明与瞳。</li><li>与主干 hopkins-tcc / 部分相干课对照，不重排课序。</li><li>薄屏假设会被 M3D 替换物体频谱，核的分离仍在。</li><li>不含胶、不含套刻。</li><li>出处：Hopkins, <em>Proc. R. Soc. A</em> 217, 408 (1953)；不发明预印本编号。</li></ul>',9))])}const D=r(C,[["render",h]]);export{F as __pageData,D as default};
